static MODES: [Mode; 1] = [
    Mode { class: &M0_CLASS, trans: &M0_TRANS, accept: &M0_ACCEPT, start: 37, accept_from: 629 },
];

/// What the lexer could not do at the error position.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LexErrorReason {
    /// No rule matches.
    NoMatch,
    /// A rule matches, but its value does not fit the Rust type (a numeral beyond `u64`).
    Unrepresentable,
    /// End of input inside a nested mode.
    EndInMode,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct LexError {
    /// Character offset, as in Lean's `LexError.pos`.
    pub pos: usize,
    /// Byte offset.
    pub byte_pos: usize,
    /// The offending character; none at end of input.
    pub ch: Option<char>,
    pub reason: LexErrorReason,
}

fn lex_error(src: &str, byte_pos: usize, reason: LexErrorReason) -> LexError {
    LexError {
        pos: src[..byte_pos].chars().count(),
        byte_pos,
        ch: src[byte_pos..].chars().next(),
        reason,
    }
}

/// The longest match from `pos`: the accepting rule plus one (0 for none) and its end.
#[inline(always)]
fn scan(mode: &Mode, src: &[u8], pos: usize) -> (usize, usize) {
    let mut row = mode.start;
    let mut i = pos;
    let mut best = 0usize;
    let mut end = pos;
    loop {
        if row >= mode.accept_from {
            best = row;
            end = i;
        }
        if i >= src.len() {
            break;
        }
        let next = mode.trans[row + mode.class[src[i] as usize] as usize] as usize;
        if next == 0 {
            break;
        }
        i += 1;
        if next == row {
            // A self-loop (a run of identifier characters, of spaces, …): the loads of
            // the following bytes do not depend on each other, so scan the run apart.
            while i < src.len()
                && mode.trans[row + mode.class[src[i] as usize] as usize] as usize == row
            {
                i += 1;
            }
        } else {
            row = next;
        }
    }
    (mode.accept[best] as usize, end)
}

/// Longest-match tokenization of `src`, appending to `out` (which is not cleared).
/// The last token pushed is the end-of-input token.
pub fn tokenize<'a>(src: &'a str, out: &mut Vec<Spanned<Tok<'a>>>) -> Result<(), LexError> {
    let bytes = src.as_bytes();
    let n = bytes.len();
    let mut pos = 0usize;
    while pos < n {
        let mode = 0;
        let (rule, end) = scan(&MODES[mode], bytes, pos);
        if rule == 0 || end == pos {
            return Err(lex_error(src, pos, LexErrorReason::NoMatch));
        }
        let r = rule - 1;
        let text = &src[pos..end];
        match mode {
            0 => match r {
                2 => out.push(Spanned { tok: Tok::LET, start: pos as u32, end: end as u32 }),
                3 => out.push(Spanned { tok: Tok::PRINT, start: pos as u32, end: end as u32 }),
                4 => out.push(Spanned { tok: Tok::IF, start: pos as u32, end: end as u32 }),
                5 => out.push(Spanned { tok: Tok::THEN, start: pos as u32, end: end as u32 }),
                6 => out.push(Spanned { tok: Tok::ELSE, start: pos as u32, end: end as u32 }),
                7 => out.push(Spanned { tok: Tok::PLUS, start: pos as u32, end: end as u32 }),
                8 => out.push(Spanned { tok: Tok::MINUS, start: pos as u32, end: end as u32 }),
                9 => out.push(Spanned { tok: Tok::TIMES, start: pos as u32, end: end as u32 }),
                10 => out.push(Spanned { tok: Tok::LPAR, start: pos as u32, end: end as u32 }),
                11 => out.push(Spanned { tok: Tok::RPAR, start: pos as u32, end: end as u32 }),
                12 => out.push(Spanned { tok: Tok::COMMA, start: pos as u32, end: end as u32 }),
                13 => out.push(Spanned { tok: Tok::SEMI, start: pos as u32, end: end as u32 }),
                14 => out.push(Spanned { tok: Tok::EQ, start: pos as u32, end: end as u32 }),
                15 => out.push(Spanned { tok: Tok::AT, start: pos as u32, end: end as u32 }),
                16 => match lexrt::to_int(text) { Some(v) => out.push(Spanned { tok: Tok::NUM(v), start: pos as u32, end: end as u32 }), None => return Err(lex_error(src, pos, LexErrorReason::Unrepresentable)) },
                17 => out.push(Spanned { tok: Tok::IDENT(text), start: pos as u32, end: end as u32 }),
                18 => out.push(Spanned { tok: Tok::STR(text), start: pos as u32, end: end as u32 }),
                0 | 1 => {}
                _ => {}
            },
            _ => {}
        }
        pos = end;
    }
    out.push(Spanned { tok: Tok::EOF, start: n as u32, end: n as u32 });
    Ok(())
}

