/// A node of the postorder trace: a shifted token or a reduction.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Node {
    /// A terminal index, or `PROD_FLAG | production`.
    pub kind: u16,
    pub start: u32,
    pub end: u32,
}

pub const PROD_FLAG: u16 = 0x8000;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Entry {
    pub state: u16,
    pub start: u32,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ParseError {
    /// Index of the offending token.
    pub token: usize,
    pub state: usize,
    pub term: u16,
}

/// Parse `tokens` (ending with the end-of-input terminal). `stack` and `nodes` are
/// scratch/output buffers and are cleared first. On success `nodes` is the postorder
/// trace and its last node is the augmented start production.
pub fn parse<T: Terminal>(
    tokens: &[Spanned<T>],
    stack: &mut Vec<Entry>,
    nodes: &mut Vec<Node>,
) -> Result<(), ParseError> {
    stack.clear();
    nodes.clear();
    stack.push(Entry { state: 0, start: 0 });
    let mut ti = 0usize;
    let mut prev_end = 0u32;
    // The state on top of `stack`, kept in a register instead of reloaded from it.
    let mut state = 0usize;
    loop {
        let dr = DEFAULT_REDUCE[state] as usize;
        let prod = if dr != NONE {
            dr
        } else {
            let (term, tstart, tend) = if ti < tokens.len() {
                (tokens[ti].tok.term(), tokens[ti].start, tokens[ti].end)
            } else {
                (EOF, prev_end, prev_end)
            };
            let a = ACTION[state * NUM_TERMINALS + term as usize] as usize;
            if a == 0 {
                return Err(ParseError { token: ti, state, term });
            }
            if a & 1 == 1 {
                stack.push(Entry { state: (a >> 1) as u16, start: tstart });
                state = a >> 1;
                nodes.push(Node { kind: term, start: tstart, end: tend });
                prev_end = tend;
                ti += 1;
                continue;
            }
            (a >> 1) - 1
        };
        let n = RHS_LEN[prod] as usize;
        if n >= stack.len() {
            return Err(ParseError { token: ti, state, term: u16::MAX });
        }
        let base = stack.len() - n;
        let start = if n > 0 { stack[base].start } else { prev_end };
        stack.truncate(base);
        let top = stack[base - 1].state as usize;
        let g = GOTO[top * NUM_NONTERMINALS + LHS[prod] as usize] as usize;
        nodes.push(Node { kind: PROD_FLAG | prod as u16, start, end: prev_end });
        if g == NONE {
            return if prod == AUG_PROD {
                Ok(())
            } else {
                Err(ParseError { token: ti, state, term: u16::MAX })
            };
        }
        stack.push(Entry { state: g as u16, start });
        state = g;
    }
}


/// A byte range of the source: the extent of a symbol, as `x_span` in an action.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Span {
    pub start: u32,
    pub end: u32,
}

/// A parse stack entry. The value of its symbol is on the stack of its type in `Stacks`.
#[derive(Clone, Copy, Debug)]
pub struct ValueEntry {
    pub state: u16,
    pub start: u32,
    pub end: u32,
}

/// The buffers of `parse_values`: the entry stack and one value stack per type.
/// Reuse one across calls to avoid reallocating.
#[derive(Default)]
pub struct Stacks<'a> {
    pub entries: Vec<ValueEntry>,
    pub v1: Vec<&'a str>,
    pub v2: Vec<i64>,
    pub v3: Vec<crate::ast::Program<'a>>,
    pub v4: Vec<std::collections::VecDeque<crate::ast::Stmt<'a>>>,
    pub v5: Vec<crate::ast::Stmt<'a>>,
    pub v6: Vec<crate::ast::Expr<'a>>,
    pub v7: Vec<std::collections::VecDeque<crate::ast::Expr<'a>>>,
}

impl<'a> Stacks<'a> {
    pub fn new() -> Self {
        Self::default()
    }


    fn clear(&mut self) {
        self.entries.clear();
        self.v1.clear();
        self.v2.clear();
        self.v3.clear();
        self.v4.clear();
        self.v5.clear();
        self.v6.clear();
        self.v7.clear();
    }
}

/// Push the value a shifted token carries onto the stack of its type.
#[inline(always)]
fn push_payload<'a>(s: &mut Stacks<'a>, t: &Tok<'a>) {
    match t {
        Tok::IDENT(v) => s.v1.push(*v),
        Tok::STR(v) => s.v1.push(*v),
        Tok::NUM(v) => s.v2.push(*v),
        #[allow(unreachable_patterns)]
        _ => {}
    }
}

/// Parse `tokens` and return the value of the start symbol, computed by the Rust actions
/// of the grammar. `stacks` is cleared first.
#[allow(unused_variables, unused_mut, unused_parens, non_snake_case, clippy::all)]
pub fn parse_values<'a>(
    tokens: &[Spanned<Tok<'a>>],
    stacks: &mut Stacks<'a>,
) -> Result<crate::ast::Program<'a>, ParseError> {
    stacks.clear();
    stacks.entries.push(ValueEntry { state: 0, start: 0, end: 0 });
    let mut ti = 0usize;
    let mut prev_end = 0u32;
    // The state on top of `stacks.entries`, kept in a register instead of reloaded from it.
    let mut state = 0usize;
    loop {
        let dr = DEFAULT_REDUCE[state] as usize;
        let prod = if dr != NONE {
            dr
        } else {
            let (term, tstart, tend) = if ti < tokens.len() {
                (tokens[ti].tok.term(), tokens[ti].start, tokens[ti].end)
            } else {
                (EOF, prev_end, prev_end)
            };
            let a = ACTION[state * NUM_TERMINALS + term as usize] as usize;
            if a == 0 {
                return Err(ParseError { token: ti, state, term });
            }
            if a & 1 == 1 {
                if ti < tokens.len() {
                    push_payload(stacks, &tokens[ti].tok);
                }
                stacks.entries.push(ValueEntry { state: (a >> 1) as u16, start: tstart, end: tend });
                state = a >> 1;
                prev_end = tend;
                ti += 1;
                continue;
            }
            (a >> 1) - 1
        };
        let __n = RHS_LEN[prod] as usize;
        if __n >= stacks.entries.len() {
            return Err(ParseError { token: ti, state, term: u16::MAX });
        }
        let __base = stacks.entries.len() - __n;
        let __start = if __n > 0 { stacks.entries[__base].start } else { prev_end };
        let Stacks { entries: __stack, v1: __s1, v2: __s2, v3: __s3, v4: __s4, v5: __s5, v6: __s6, v7: __s7 } = &mut *stacks;
        match prod {
            AUG_PROD => {
                return Ok(__s3.pop().unwrap());
            }
        0 => {
            // program, alternative 1
            let ss_span = Span { start: __stack[__base + 0].start, end: __stack[__base + 0].end };
            let ss = __s4.pop().unwrap();
            __s3.push({
crate::ast::Program { stmts: ss, count: 7 }
            });
        }
        1 => {
            // stmts, alternative 1
            let rest_span = Span { start: __stack[__base + 2].start, end: __stack[__base + 2].end };
            let rest = __s4.pop().unwrap();
            let s_span = Span { start: __stack[__base + 0].start, end: __stack[__base + 0].end };
            let s = __s5.pop().unwrap();
            __s4.push({
let mut rest = rest; rest.push_front(s); rest
            });
        }
        2 => {
            // stmts, alternative 2
            __s4.push({
std::collections::VecDeque::new()
            });
        }
        3 => {
            // stmt, alternative 1
            let e_span = Span { start: __stack[__base + 3].start, end: __stack[__base + 3].end };
            let e = __s6.pop().unwrap();
            let x_span = Span { start: __stack[__base + 1].start, end: __stack[__base + 1].end };
            let x = __s1.pop().unwrap();
            __s5.push({
crate::ast::Stmt::Bind { name: x, value: e, index: 1 }
            });
        }
        4 => {
            // stmt, alternative 2
            let e_span = Span { start: __stack[__base + 1].start, end: __stack[__base + 1].end };
            let e = __s6.pop().unwrap();
            __s5.push({
crate::ast::Stmt::Print(e)
            });
        }
        5 => {
            // expr, alternative 1
            let e_span = Span { start: __stack[__base + 5].start, end: __stack[__base + 5].end };
            let e = __s6.pop().unwrap();
            let t_span = Span { start: __stack[__base + 3].start, end: __stack[__base + 3].end };
            let t = __s6.pop().unwrap();
            let c_span = Span { start: __stack[__base + 1].start, end: __stack[__base + 1].end };
            let c = __s6.pop().unwrap();
            __s6.push({
crate::ast::Expr::Cond(Box::new(c), Box::new(t), Some(Box::new(e)))
            });
        }
        6 => {
            // expr, alternative 2
            let t_span = Span { start: __stack[__base + 3].start, end: __stack[__base + 3].end };
            let t = __s6.pop().unwrap();
            let c_span = Span { start: __stack[__base + 1].start, end: __stack[__base + 1].end };
            let c = __s6.pop().unwrap();
            __s6.push({
crate::ast::Expr::Cond(Box::new(c), Box::new(t), None)
            });
        }
        7 => {
            // expr, alternative 3
            // identity: the value stays where it is
        }
        8 => {
            // sum, alternative 1
            let b_span = Span { start: __stack[__base + 2].start, end: __stack[__base + 2].end };
            let b = __s6.pop().unwrap();
            let a_span = Span { start: __stack[__base + 0].start, end: __stack[__base + 0].end };
            let a = __s6.pop().unwrap();
            __s6.push({
crate::ast::Expr::Bin(crate::ast::Op::Add, Box::new(a), Box::new(b))
            });
        }
        9 => {
            // sum, alternative 2
            let b_span = Span { start: __stack[__base + 2].start, end: __stack[__base + 2].end };
            let b = __s6.pop().unwrap();
            let a_span = Span { start: __stack[__base + 0].start, end: __stack[__base + 0].end };
            let a = __s6.pop().unwrap();
            __s6.push({
crate::ast::Expr::Bin(crate::ast::Op::Sub, Box::new(a), Box::new(b))
            });
        }
        10 => {
            // sum, alternative 3
            // identity: the value stays where it is
        }
        11 => {
            // prod, alternative 1
            let b_span = Span { start: __stack[__base + 2].start, end: __stack[__base + 2].end };
            let b = __s6.pop().unwrap();
            let a_span = Span { start: __stack[__base + 0].start, end: __stack[__base + 0].end };
            let a = __s6.pop().unwrap();
            __s6.push({
crate::ast::Expr::Bin(crate::ast::Op::Mul, Box::new(a), Box::new(b))
            });
        }
        12 => {
            // prod, alternative 2
            // identity: the value stays where it is
        }
        13 => {
            // atom, alternative 1
            let n_span = Span { start: __stack[__base + 0].start, end: __stack[__base + 0].end };
            let n = __s2.pop().unwrap();
            __s6.push({
crate::ast::Expr::Num(n)
            });
        }
        14 => {
            // atom, alternative 2
            let a_span = Span { start: __stack[__base + 1].start, end: __stack[__base + 1].end };
            let a = __s6.pop().unwrap();
            __s6.push({
crate::ast::Expr::Neg(Box::new(a))
            });
        }
        15 => {
            // atom, alternative 3
            let x_span = Span { start: __stack[__base + 0].start, end: __stack[__base + 0].end };
            let x = __s1.pop().unwrap();
            __s6.push({
crate::ast::Expr::Var(x)
            });
        }
        16 => {
            // atom, alternative 4
            let x_span = Span { start: __stack[__base + 0].start, end: __stack[__base + 0].end };
            let x = __s1.pop().unwrap();
            __s6.push({
crate::ast::Expr::Located(x, x_span)
            });
        }
        17 => {
            // atom, alternative 5
            let s_span = Span { start: __stack[__base + 0].start, end: __stack[__base + 0].end };
            let s = __s1.pop().unwrap();
            __s6.push({
crate::ast::Expr::Str(s)
            });
        }
        18 => {
            // atom, alternative 6
            let s_span = Span { start: __stack[__base + 0].start, end: __stack[__base + 0].end };
            let s = __s1.pop().unwrap();
            __s6.push({
crate::ast::Expr::Len(s.chars().count() as u64)
            });
        }
        19 => {
            // atom, alternative 7
            let args_span = Span { start: __stack[__base + 2].start, end: __stack[__base + 2].end };
            let args = __s7.pop().unwrap();
            let f_span = Span { start: __stack[__base + 0].start, end: __stack[__base + 0].end };
            let f = __s1.pop().unwrap();
            __s6.push({
crate::ast::Expr::Call(f, args)
            });
        }
        20 => {
            // atom, alternative 8
            let b_span = Span { start: __stack[__base + 3].start, end: __stack[__base + 3].end };
            let b = __s6.pop().unwrap();
            let a_span = Span { start: __stack[__base + 1].start, end: __stack[__base + 1].end };
            let a = __s6.pop().unwrap();
            __s6.push({
crate::ast::Expr::Pair(Box::new((a, b)))
            });
        }
        21 => {
            // atom, alternative 9
            let c_span = Span { start: __stack[__base + 5].start, end: __stack[__base + 5].end };
            let c = __s6.pop().unwrap();
            let b_span = Span { start: __stack[__base + 3].start, end: __stack[__base + 3].end };
            let b = __s6.pop().unwrap();
            let a_span = Span { start: __stack[__base + 1].start, end: __stack[__base + 1].end };
            let a = __s6.pop().unwrap();
            __s6.push({
crate::ast::Expr::Triple(Box::new((a, b, c)))
            });
        }
        22 => {
            // atom, alternative 10
            let e_span = Span { start: __stack[__base + 1].start, end: __stack[__base + 1].end };
            let e = __s6.pop().unwrap();
            __s6.push({
e
            });
        }
        23 => {
            // separated_list_COMMA_expr, alternative 1
            __s7.push({
std::collections::VecDeque::new()
            });
        }
        24 => {
            // separated_list_COMMA_expr, alternative 2
            let x_span = Span { start: __stack[__base + 0].start, end: __stack[__base + 0].end };
            let x = __s6.pop().unwrap();
            __s7.push({
std::collections::VecDeque::from([x])
            });
        }
        25 => {
            // separated_list_COMMA_expr, alternative 3
            let xs_span = Span { start: __stack[__base + 2].start, end: __stack[__base + 2].end };
            let xs = __s7.pop().unwrap();
            let x_span = Span { start: __stack[__base + 0].start, end: __stack[__base + 0].end };
            let x = __s6.pop().unwrap();
            __s7.push({
{ let mut xs = xs; xs.push_front(x); xs }
            });
        }
            _ => unreachable!(),
        }
        __stack.truncate(__base);
        let __top = __stack[__base - 1].state as usize;
        let __g = GOTO[__top * NUM_NONTERMINALS + LHS[prod] as usize] as usize;
        if __g == NONE {
            return Err(ParseError { token: ti, state, term: u16::MAX });
        }
        __stack.push(ValueEntry { state: __g as u16, start: __start, end: prev_end });
        state = __g;
    }
}
